            "attacker_controlled": true,
            "validation_layers": [
              "Transaction validation",
              "EIP-7702 authorization processing"
            ],
            "bug_bounty_scope": "in-scope",
            "notes": "Attacker can replay an Authorization signed for one chain on a different chain if chain_id validation is missing."
