          "property_id": "PROP-W6B15-5",
          "title": "Verify Trust Boundary Integrity for tb-006: Is EIP-7702 Authorization nonce validation correctly enforced?",
          "severity": "Critical",
          "mindset": "Boundary Guard",
          "is_boundary_check": true,
          "reachability": {
            "classification": "external-reachable",
            "entry_points": [
              "Transaction",
              "P2P"
            ],
            "attacker_controlled": true,
            "validation_layers": [
              "Transaction validation",
              "Nonce verification"
            ],
            "bug_bounty_scope": "in-scope",
            "notes": "Attacker can attempt to replay a previously-used Authorization by resubmitting with a stale nonce."
          },
          "test_procedure": "1. Identify all code paths where EIP-7702 Authorization tuples are received and processed.\n2. Locate the nonce verification logic that compares authorization.nonce against account.nonce.\n3. Verify that the nonce check occurs BEFORE any authorization processing or state changes.\n4. Attempt to submit a transaction with an Authorization tuple containing a stale nonce.\n5. Verify the authorization is explicitly rejected and no code delegation occurs.\n6. Check error handling to ensure rejection is clean and does not leak sensitive state.\n7. Test boundary case where nonce equals MAX_UINT64 to verify proper overflow handling.",
          "bug_class": "Input Validation",
          "risk_category": "Tampering",
          "notes": "Source: PROP-W6B15-5, Trust Boundary: tb-006, Source Assumption: asm-006, Invariant: SG-004/INV-004"
        },
