            "entry_points": [
              "Transaction",
              "P2P"
            ],
            "attacker_controlled": true,
            "validation_layers": [
              "Transaction validation",
              "Nonce verification"
            ],
            "bug_bounty_scope": "in-scope",
            "notes": "Attacker can attempt to replay a previously-used Authorization by resubmitting with a stale nonce."
          },
          "test_procedure": "1. Create a valid EIP-7702 Authorization tuple with the current nonce of the authorizing account.\n2. Submit the transaction and confirm the authorization is accepted and processed.\n3. Verify the authorizer's nonce has been incremented after successful processing.\n4. Capture the original Authorization tuple (with the now-stale nonce).\n5. Attempt to replay the captured Authorization in a new transaction.\n6. Verify the replayed authorization is rejected with an appropriate error.\n7. Confirm no partial state changes occurred during the failed replay attempt.\n8. Test replay via P2P propagation to verify rejection occurs at network level.",
          "bug_class": "Replay Attack",
          "risk_category": "Spoofing",
          "notes": "Source: PROP-W6B15-5, Trust Boundary: tb-006, Replay prevention via nonce verification"
        },
